function makeRect(x, y, w, h, dltAng = 0) {
	const rectPts = [];
	for (let i = 0; i < 4; i++) {
		const angle = (i / 4) * Math.PI * 2 + dltAng + (Math.random() * 0.6 - 0.3);
		const px = x + w * Math.cos(angle);
		const py = y + h * Math.sin(angle);
		rectPts.push(new Point(px, py));
	}
	if (DBG) rect(x-w/2,y-h/2,w,h)
	return new Polygon(rectPts, true);
}
function makeCirc(x, y, w, h, dltAng = 0) {
	if (DBG) ellipse(x,y,w,h)
	return Polygon.createArc([x, y], [w, h], 0, Math.PI * 2).sparsify(20);
}
function createRandShape() {
	const rectShape1 = makeRect(random(250, 350), random(100, 300), random(100, 300), random(100, 300), Math.PI / 6 + random(-1, 1));
	const rectShape2 = makeRect(random(250, 350), random(100, 300), random(100, 300), random(100, 300), Math.PI / 6 + random(-1, 1));
	const circleShape1 = makeCirc(random(200, 600), random(250, 550), random(150, 350), random(150, 350));
	const circleShape2 = makeCirc(random(200, 600), random(250, 550), random(150, 350), random(150, 350));

	const epiShape = Polygon.outerHull(rectShape1, rectShape2, circleShape1, circleShape2);

	epiShape.densify(25).jitter(5);

	return epiShape;
}

function calcLongSeg(rings, vec = null) {
	if (vec == null) vec = {
		v1: createVector(0, 0),
		v2: createVector(0, 0),
		l: 0
	};
	// console.log("calcLongSeg " + rings);

	for (const pts of rings) {
		for (let i = 1; i < pts.length; i++) {
			const v1 = createVector(pts[i - 1].x, pts[i - 1].y);
			const v2 = createVector(pts[i].x, pts[i].y);
			const l = p5.Vector.dist(v1, v2);
			if (l > vec.l) vec = { v1, v2, l };
		}
	}

	return vec;
}
